#!/usr/bin/env node
// SEO generator for the static site. Source of truth: seo/site.json + assets/data/store.json.
//
//   node scripts/seo.js build   rewrite each page's <!-- seo --> head block and regenerate
//                               sitemap.xml, robots.txt and llms.txt
//   node scripts/seo.js check   fail if any generated file is out of date (use before commits / in CI)
//
// The head block holds the title, meta description, canonical, Open Graph and Twitter tags and
// one JSON-LD @graph per page (Organization, WebSite, WebPage, plus Product with an Offer when
// the price is confirmed). Values come from the same JSON the store uses, so markup always
// matches the visible price.
'use strict';
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const root = path.resolve(__dirname, '..');
const read = (f) => fs.readFileSync(path.join(root, f), 'utf8');
const site = JSON.parse(read('seo/site.json'));
const store = JSON.parse(read('assets/data/store.json'));
const O = site.origin.replace(/\/$/, '');
const abs = (p) => O + '/' + String(p).replace(/^\//, '');
const pageUrl = (pg) => (pg.path === '/' ? O + '/' : O + pg.path);
const ORG = O + '/#organization';
const WEB = O + '/#website';

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const jsonld = (obj) => JSON.stringify(obj).replace(/</g, '\\u003c');

function organization() {
  const o = site.org;
  return {
    '@type': 'Organization', '@id': ORG,
    name: o.name, alternateName: o.alternateName, url: O + '/',
    logo: { '@type': 'ImageObject', url: abs(o.logo), width: 512, height: 512 },
    description: o.description, slogan: o.slogan, email: o.email,
    contactPoint: { '@type': 'ContactPoint', contactType: 'customer support', email: o.email, availableLanguage: ['English', 'Filipino'] },
    sameAs: o.sameAs,
  };
}

function website() {
  return { '@type': 'WebSite', '@id': WEB, url: O + '/', name: site.siteName, alternateName: site.org.alternateName, inLanguage: site.locale, publisher: { '@id': ORG } };
}

function shippingDetails() {
  const s = store.shipping;
  const days = (d) => ({ '@type': 'ShippingDeliveryTime', transitTime: { '@type': 'QuantitativeValue', minValue: d[0], maxValue: d[1], unitCode: 'DAY' } });
  const region = (ccs) => ccs.map((cc) => ({ '@type': 'DefinedRegion', addressCountry: cc }));
  return s.zones.map((z) => {
    const free = z.countries.every((cc) => s.freeCountries.includes(cc));
    return {
      '@type': 'OfferShippingDetails',
      shippingLabel: s.carrier + ' from ' + s.origin + ': ' + z.label,
      shippingRate: free ? { '@type': 'MonetaryAmount', value: 0, currency: 'PHP' } : { '@type': 'MonetaryAmount', value: s.flatUsd, currency: 'USD' },
      shippingDestination: region(z.countries),
      deliveryTime: days(z.days),
    };
  });
}

function product(pg) {
  const p = store.products[pg.product];
  const url = pageUrl(pg);
  const node = {
    '@type': 'Product', '@id': url + '#product',
    name: pg.productName, description: pg.productDescription, category: pg.category,
    image: pg.productImages.map(abs), url,
    brand: { '@type': 'Brand', name: 'Naga' }, manufacturer: { '@id': ORG },
    countryOfAssembly: 'Philippines',
  };
  if (p && p.priceConfirmed && p.php) {
    node.offers = {
      '@type': 'Offer', url: url + '#buy',
      price: p.php, priceCurrency: 'PHP',
      availability: p.mode === 'preorder' ? 'https://schema.org/PreOrder' : 'https://schema.org/InStock',
      itemCondition: 'https://schema.org/NewCondition',
      seller: { '@id': ORG },
      shippingDetails: shippingDetails(),
    };
  }
  return node;
}

function graph(pg) {
  const url = pageUrl(pg);
  const page = {
    '@type': pg.type, '@id': url + '#webpage', url, name: pg.title, description: pg.description,
    inLanguage: site.locale, isPartOf: { '@id': WEB },
    primaryImageOfPage: { '@type': 'ImageObject', url: abs(pg.image), width: 1200, height: 630 },
  };
  const nodes = [organization(), website(), page];
  // A Product node only once it has an Offer: Google reports Product markup without
  // offers, review or rating as an invalid item. The page itself still names the product.
  if (pg.product) {
    const prod = product(pg);
    if (prod.offers) { nodes.push(prod); page.mainEntity = { '@id': prod['@id'] }; }
  }
  if (pg.type === 'AboutPage') page.mainEntity = { '@id': ORG };
  if (pg.extraGraph) nodes.push(...pg.extraGraph);
  return { '@context': 'https://schema.org', '@graph': nodes };
}

function headBlock(pg) {
  const url = pageUrl(pg);
  return [
    '<!-- seo: generated by scripts/seo.js from seo/site.json; edit there, then run `npm run seo` -->',
    `<title>${esc(pg.title)}</title>`,
    `<meta name="description" content="${esc(pg.description)}">`,
    `<link rel="canonical" href="${url}">`,
    `<meta property="og:type" content="website">`,
    `<meta property="og:site_name" content="${esc(site.siteName)}">`,
    `<meta property="og:title" content="${esc(pg.title)}">`,
    `<meta property="og:description" content="${esc(pg.description)}">`,
    `<meta property="og:url" content="${url}">`,
    `<meta property="og:image" content="${abs(pg.image)}">`,
    `<meta property="og:image:width" content="1200">`,
    `<meta property="og:image:height" content="630">`,
    `<meta property="og:image:alt" content="${esc(pg.imageAlt)}">`,
    `<meta name="twitter:card" content="summary_large_image">`,
    `<script type="application/ld+json">\n${jsonld(graph(pg))}\n</script>`,
    '<!-- /seo -->',
  ].join('\n');
}

const BLOCK = /<!-- seo:[\s\S]*?<!-- \/seo -->/;

function withHead(html, pg) {
  const block = headBlock(pg);
  if (BLOCK.test(html)) return html.replace(BLOCK, () => block);
  // First run: drop the hand-written title and description, insert the block in their place.
  const stripped = html.replace(/^<title>.*<\/title>\n/m, '').replace(/^<meta name="description"[^>]*>\n/m, '');
  return stripped.replace('<link rel="icon"', () => block + '\n<link rel="icon"');
}

function lastmod(file) {
  try {
    const dirty = execFileSync('git', ['status', '--porcelain', '--', file], { cwd: root }).toString().trim();
    if (!dirty) {
      const d = execFileSync('git', ['log', '-1', '--format=%cs', '--', file], { cwd: root }).toString().trim();
      if (d) return d;
    }
  } catch (e) { /* not a git checkout */ }
  return new Date().toISOString().slice(0, 10);
}

function sitemap() {
  const urls = site.pages.map((pg) => `  <url>\n    <loc>${pageUrl(pg)}</loc>\n    <lastmod>${lastmod(pg.file)}</lastmod>\n  </url>`);
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls.join('\n')}\n</urlset>\n`;
}

function robots() {
  return [
    '# Naga Industries. Generated by scripts/seo.js.',
    '# Every crawler is welcome, AI search, AI assistants and AI training included:',
    '# Naga wants its products described accurately wherever people ask.',
    '# To opt out of AI training only, add a group for GPTBot, ClaudeBot, CCBot,',
    '# Google-Extended and Applebot-Extended (see .claude/skills/ai-agent-readiness).',
    'User-agent: *',
    'Disallow: /api/',
    '',
    `Sitemap: ${O}/sitemap.xml`,
    '',
  ].join('\n');
}

function llms() {
  const P = store.products;
  const price = (k) => {
    const p = P[k];
    if (!p || !p.php) return 'Price to be announced';
    if (!p.priceConfirmed) return 'Price to be confirmed';
    return '₱' + p.php.toLocaleString('en-US') + ' (about US$' + p.usd.toLocaleString('en-US') + ')';
  };
  const s = store.shipping;
  const byFile = Object.fromEntries(site.pages.map((pg) => [pg.file, pg]));
  const link = (file, note) => `- [${byFile[file].title.split(' | ')[0]}](${pageUrl(byFile[file])}): ${note}`;
  const extra = site.pages.filter((pg) => pg.llms).map((pg) => link(pg.file, pg.llms));
  return [
    '# Naga Industries',
    '',
    `> ${site.org.description}`,
    '',
    'Facts below match the website. Product names (SIPAG, LAKAN, DIWA, Baku) and the motto Sulong ("forward") are Filipino words.',
    '',
    '## Products',
    '',
    link('lakan-ii.html', `gaming laptop. Intel Core 7 250H, NVIDIA GeForce RTX 5060 Laptop GPU at up to 115W, 16GB DDR5-5600, 512GB PCIe Gen4 SSD, 15.6-inch display. ${price('lakan-ii')}, Naga Karga backpack included. Pre-order.`),
    link('sipag-i.html', `productivity laptop. Intel Core Ultra 5 125U, 14-inch Full HD, 60Wh battery for up to 13 hours, 1.30 kg, USB-C charging. ${price('sipag-i')}. Pre-order.`),
    link('diwa.html', 'AI mini PC that runs Baku, Naga\'s own local AI. Coming soon, no price yet; reservations are open.'),
    '',
    '## Baku',
    '',
    '- Baku is Naga\'s own AI. It runs on DIWA itself, keeps data on the machine, works offline and speaks every language. It is being built with the Machine.Fun ecosystem: https://machine.fun/project/J8RKZwmr8ol',
    '',
    '## Buying and shipping',
    '',
    `- Shipping: free in the Philippines; US$${s.flatUsd} flat rate worldwide by ${s.carrier} from ${s.origin}, ${Math.min(...s.zones.map((z) => z.days[0]))} to ${s.rest.days[1]} days by zone.`,
    `- Contact: ${site.org.email}`,
    ...(extra.length ? ['', '## Guides', '', ...extra] : []),
    '',
    '## Optional',
    '',
    link('about.html', 'company facts in one place.'),
    ...site.org.sameAs.map((u) => `- [${/facebook/.test(u) ? 'Facebook' : 'Instagram'}](${u}): official account.`),
    '',
  ].join('\n');
}

function outputs() {
  const files = {};
  for (const pg of site.pages) {
    const f = path.join(root, pg.file);
    if (!fs.existsSync(f)) { console.warn('skip (missing): ' + pg.file); continue; }
    files[pg.file] = withHead(fs.readFileSync(f, 'utf8'), pg);
  }
  files['sitemap.xml'] = sitemap();
  files['robots.txt'] = robots();
  files['llms.txt'] = llms();
  return files;
}

const cmd = process.argv[2] || 'build';
const out = outputs();
if (cmd === 'build') {
  for (const [f, body] of Object.entries(out)) {
    const p = path.join(root, f);
    const before = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null;
    if (before !== body) { fs.writeFileSync(p, body); console.log('wrote ' + f); }
  }
} else if (cmd === 'check') {
  const stale = Object.entries(out).filter(([f, body]) => {
    const p = path.join(root, f);
    if (f === 'sitemap.xml' && fs.existsSync(p)) return fs.readFileSync(p, 'utf8').replace(/<lastmod>.*<\/lastmod>/g, '') !== body.replace(/<lastmod>.*<\/lastmod>/g, '');
    return !fs.existsSync(p) || fs.readFileSync(p, 'utf8') !== body;
  }).map(([f]) => f);
  if (stale.length) { console.error('Out of date, run `npm run seo`: ' + stale.join(', ')); process.exit(1); }
  console.log('SEO files are up to date.');
} else {
  console.error('usage: node scripts/seo.js build|check'); process.exit(2);
}
